        [MenuItem("Bellerophon/Bootstrap/Restore Approved Control Room Current State Snapshot")]
        public static void RestoreCapturedControlRoomCurrentState()
        {
            var activeScene = SceneManager.GetActiveScene();
            if (!activeScene.IsValid())
            {
                throw new InvalidOperationException("No active scene is open for control room current state restore.");
            }

            var normalizedActivePath = activeScene.path.Replace('\\', '/');
            var normalizedCargoPath = Phase4CargoShipGrayboxBootstrap.CargoRunScenePath.Replace('\\', '/');
            if (!string.Equals(normalizedActivePath, normalizedCargoPath, StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("Current active scene is not CargoRunMvp. ActiveScene=" + activeScene.path);
            }

            var applied = 0;
            for (var i = 0; i < Roots.Length; i++)
            {
                var root = RequireRoot(Roots[i].Name);
                for (var j = 0; j < Roots[i].Objects.Length; j++)
                {
                    ApplyObject(root.transform, Roots[i].Objects[j]);
                    applied++;
                }
            }

            EditorUtility.SetDirty(SceneManager.GetActiveScene().GetRootGameObjects()[0]);
            Debug.Log("Approved control room current state snapshot restored. CapturedAt=" + CapturedAt + "; Roots=" + Roots.Length.ToString(CultureInfo.InvariantCulture) + "; Objects=" + applied.ToString(CultureInfo.InvariantCulture));
        }

        private static void ApplyObject(Transform root, CapturedObject captured)
        {
            var transform = FindByIndexPath(root, captured.IndexPath);
            if (transform == null)
            {
                throw new InvalidOperationException("Missing captured control room object: " + root.name + "/" + captured.NamePath + " [" + captured.IndexPath + "]");
            }

            if (!string.Equals(transform.name, captured.Name, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Captured control room object name mismatch: expected " + captured.Name + ", actual " + transform.name + ", indexPath=" + captured.IndexPath);
            }

            var componentSignature = GetComponentSignature(transform.gameObject);
            if (!string.Equals(componentSignature, captured.ComponentSignature, StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Captured control room object component mismatch: " + root.name + "/" + captured.NamePath);
            }

            transform.localPosition = captured.LocalPosition;
            transform.localRotation = captured.LocalRotation;
            transform.localScale = captured.LocalScale;
            transform.gameObject.SetActive(captured.ActiveSelf);

            var renderer = transform.GetComponent<Renderer>();
            if ((renderer != null) != captured.HasRenderer)
            {
                throw new InvalidOperationException("Captured control room object renderer mismatch: " + root.name + "/" + captured.NamePath);
            }

            if (renderer == null)
            {
                return;
            }

            renderer.enabled = captured.RendererEnabled;
            ApplyMaterialPaths(renderer, captured.MaterialPaths);
        }

        private static void ApplyMaterialPaths(Renderer renderer, string[] materialPaths)
        {
            if (materialPaths == null || materialPaths.Length == 0)
            {
                return;
            }

            var materials = renderer.sharedMaterials;
            if (materials.Length != materialPaths.Length)
            {
                throw new InvalidOperationException("Captured material count mismatch: " + renderer.name);
            }

            var changed = false;
            for (var i = 0; i < materialPaths.Length; i++)
            {
                if (string.IsNullOrWhiteSpace(materialPaths[i]))
                {
                    continue;
                }

                var material = AssetDatabase.LoadAssetAtPath<Material>(materialPaths[i]);
                if (material == null)
                {
                    throw new InvalidOperationException("Captured material asset was not found: " + materialPaths[i]);
                }

                materials[i] = material;
                changed = true;
            }

            if (changed)
            {
                renderer.sharedMaterials = materials;
            }
        }

        private static GameObject RequireRoot(string rootName)
        {
            var roots = SceneManager.GetActiveScene().GetRootGameObjects();
            for (var i = 0; i < roots.Length; i++)
            {
                if (roots[i] != null && string.Equals(roots[i].name, rootName, StringComparison.Ordinal))
                {
                    return roots[i];
                }
            }

            throw new InvalidOperationException("Missing captured control room root: " + rootName);
        }

        private static Transform FindByIndexPath(Transform root, string indexPath)
        {
            if (string.Equals(indexPath, ".", StringComparison.Ordinal))
            {
                return root;
            }

            var current = root;
            var parts = indexPath.Split('/');
            for (var i = 0; i < parts.Length; i++)
            {
                if (!int.TryParse(parts[i], NumberStyles.Integer, CultureInfo.InvariantCulture, out var index) || index < 0 || index >= current.childCount)
                {
                    return null;
                }

                current = current.GetChild(index);
            }

            return current;
        }

        private static string GetComponentSignature(GameObject obj)
        {
            var components = obj.GetComponents<Component>();
            var builder = new StringBuilder();
            for (var i = 0; i < components.Length; i++)
            {
                if (i > 0)
                {
                    builder.Append("|");
                }

                builder.Append(components[i] == null ? "<missing>" : components[i].GetType().FullName);
            }

            return builder.ToString();
        }

        private readonly struct CapturedRoot
        {
            public CapturedRoot(string name, CapturedObject[] objects)
            {
                Name = name;
                Objects = objects;
            }

            public string Name { get; }
            public CapturedObject[] Objects { get; }
        }

        private readonly struct CapturedObject
        {
            public CapturedObject(string indexPath, string namePath, string name, Vector3 localPosition, Quaternion localRotation, Vector3 localScale, bool activeSelf, string componentSignature, bool hasRenderer, bool rendererEnabled, string[] materialPaths)
            {
                IndexPath = indexPath;
                NamePath = namePath;
                Name = name;
                LocalPosition = localPosition;
                LocalRotation = localRotation;
                LocalScale = localScale;
                ActiveSelf = activeSelf;
                ComponentSignature = componentSignature;
                HasRenderer = hasRenderer;
                RendererEnabled = rendererEnabled;
                MaterialPaths = materialPaths;
            }

            public string IndexPath { get; }
            public string NamePath { get; }
            public string Name { get; }
            public Vector3 LocalPosition { get; }
            public Quaternion LocalRotation { get; }
            public Vector3 LocalScale { get; }
            public bool ActiveSelf { get; }
            public string ComponentSignature { get; }
            public bool HasRenderer { get; }
            public bool RendererEnabled { get; }
            public string[] MaterialPaths { get; }
        }
    }
